use crate::layout::Rect;use notepad_core::{ColorOrder,LineColour};#[derive(Debug,Clone)]pub struct ExtractPanelState{pub bounds:Rect,pub selected_colours:Vec<LineColour>,pub order:ColorOrder,pub preview:String}impl Default for ExtractPanelState{fn default()->Self{Self{bounds:Rect::default(),selected_colours:Vec::new(),order:ColorOrder::Document,preview:String::new()}}}impl ExtractPanelState{pub fn toggle_colour(&mut self,c:LineColour){if let Some(i)=self.selected_colours.iter().position(|x|*x==c){self.selected_colours.remove(i);}else{self.selected_colours.push(c)}}}
